@startuml
class Driver {
  + driverID : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licensePlate : string
  + isInRepairShop : boolean
}

class Route {
  + routeNumber : int
}

class Shift {
  + shiftType : string
}

class Schedule {
  + date : date
}

class Assignment {
  + shiftID : int
}

Route "1" -- "0..*" Assignment
Bus "1" -- "0..*" Assignment
Driver "1" -- "0..*" Assignment
Assignment "1" -- "1" Shift
Assignment "1" -- "1" Schedule

class CityStaff {}

CityStaff "1" -- "0..*" Route : manages
CityStaff "1" -- "0..*" Driver : manages
CityStaff "1" -- "0..*" Bus : manages
@enduml

